here_quoted.input:
PROBE=/out/c3_probe; export PROBE
{
v=EXPANDED; "$PROBE" copy <<'DOC'
$v $((2+3)) $(printf hidden) `printf hidden` \literal
DOC
} > /out/c3_here_quoted.stdout

here_sealed_read_only.input:
PROBE=/out/c3_probe; export PROBE
{
"$PROBE" read_only <<DOC
original_document
DOC
} > /out/c3_here_sealed_read_only.stdout

here_pipeline_source.input:
PROBE=/out/c3_probe; export PROBE
{
"$PROBE" copy <<DOC | "$PROBE" copy
pipeline_document
DOC
} > /out/c3_here_pipeline_source.stdout

here_pipeline_override.input:
PROBE=/out/c3_probe; export PROBE
{
"$PROBE" copy </out/c3_empty | "$PROBE" copy <<DOC
last_stdin_document
DOC
} > /out/c3_here_pipeline_override.stdout

here_command_substitution.input:
PROBE=/out/c3_probe; export PROBE
{
v=$("$PROBE" copy <<DOC
substitution_document
DOC
); printf 'captured=<%s>\n' "$v"
} > /out/c3_here_command_substitution.stdout

here_redirection_failure_cleanup.input:
PROBE=/out/c3_probe; export PROBE
{
if "$PROBE" copy <<DOC >/missing/c3_file; then printf BAD; else printf 'C3_REDIR_RECOVERED\n'; fi
unused_document
DOC
} > /out/c3_here_redirection_failure_cleanup.stdout

